'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var uniform = require( '@stdlib/random/base/uniform' );
var expf = require( '@stdlib/math/base/special/expf' );
var expm1f = require( '@stdlib/math/base/special/expm1f' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var log1pf = require( '@stdlib/math/base/special/log1pf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var EPS = require( '@stdlib/constants/float32/eps' );
var LN2 = require( '@stdlib/constants/float32/ln-two' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var log1mexpf = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );
var large = require( './fixtures/python/large.json' );
var small = require( './fixtures/python/small.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof log1mexpf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the natural logarithm of `1-exp(-|x|)` (`0 < |x| <= ln(2)`)', function test( t ) {
	var rand;
	var x;
	var y;
	var v;
	var i;

	rand = uniform.factory( f32( EPS ), LN2, {
		'seed': 129
	});
	for ( i = 0; i < 1e3; i++ ) {
		v = f32( rand() );
		x = log1mexpf( v );
		y = lnf( f32( -expm1f( f32( -v ) ) ) );
		t.strictEqual( x, y, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the natural logarithm of `1-exp(-|x|)` (`|x| > ln(2)`)', function test( t ) {
	var rand;
	var x;
	var y;
	var v;
	var i;

	rand = uniform.factory( f32( LN2 + EPS ), f32( 100.0 ), {
		'seed': 91919
	});
	for ( i = 0; i < 1e3; i++ ) {
		v = f32( rand() );
		x = log1mexpf( v );
		y = log1pf( f32( -expf( f32( -v ) ) ) );
		t.strictEqual( x, y, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1-exp(-|x|)`', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = data.x;
	expected = data.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = log1mexpf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1-exp(-|x|)` (small values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = small.x;
	expected = small.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = log1mexpf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1-exp(-|x|)` (large values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = large.x;
	expected = large.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = log1mexpf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v = log1mexpf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-Infinity` if provided `+-0`', function test( t ) {
	var v;

	v = log1mexpf( 0.0 );
	t.strictEqual( v, NINF, 'returns expected value' );

	v = log1mexpf( -0.0 );
	t.strictEqual( v, NINF, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-0` if provided `+-Infinity`', function test( t ) {
	var v;

	v = log1mexpf( PINF );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	v = log1mexpf( NINF );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function is an even function (log1mexpf(-x) === log1mexpf(x))', function test( t ) {
	var values;
	var v;
	var i;

	values = [ 0.1, 0.5, 0.625, 1.0, 2.0, 5.0, 10.0, 50.0, 80.0 ];
	for ( i = 0; i < values.length; i++ ) {
		v = f32( values[ i ] );
		t.strictEqual( log1mexpf( -v ), log1mexpf( v ), 'returns expected value' );
	}
	t.end();
});
